Here's a minimal API endpoint handling multiple image files + a description field with a 50 MB limit:

```csharp
using Microsoft.AspNetCore.Http.Features;

var builder = WebApplication.CreateBuilder(args);

// Configure max request body size
builder.WebHost.ConfigureKestrel(options =>
{
    options.Limits.MaxRequestBodySize = 50 * 1024 * 1024; // 50 MB
});

var app = builder.Build();

app.MapPost("/upload", async (HttpRequest request) =>
{
    // Ensure it's a multipart form request
    if (!request.HasFormContentType)
        return Results.BadRequest("Expected a multipart form request.");

    var form = await request.ReadFormAsync();

    var description = form["description"].ToString();
    var files = form.Files.GetFiles("images");

    if (files.Count == 0)
        return Results.BadRequest("No image files provided.");

    var savedFiles = new List<string>();

    foreach (var file in files)
    {
        // Validate content type
        if (!file.ContentType.StartsWith("image/"))
            return Results.BadRequest($"File '{file.FileName}' is not an image.");

        var savePath = Path.Combine("uploads", $"{Guid.NewGuid()}{Path.GetExtension(file.FileName)}");
        Directory.CreateDirectory("uploads");

        await using var stream = File.Create(savePath);
        await file.CopyToAsync(stream);

        savedFiles.Add(savePath);
    }

    return Results.Ok(new { description, uploadedFiles = savedFiles });
})
.DisableAntiforgery()                          // required for minimal APIs accepting forms without tokens
.WithMetadata(new RequestFormLimitsAttribute    // per-endpoint form size limit
{
    MultipartBodyLengthLimit = 50 * 1024 * 1024
});

app.Run();
```

**Key points:**

- **`Kestrel MaxRequestBodySize`** — raises the server-level cap to 50 MB.
- **`RequestFormLimitsAttribute`** — sets the per-endpoint multipart limit (otherwise defaults to ~128 MB but Kestrel's limit takes precedence).
- **`DisableAntiforgery()`** — needed in .NET 8+ minimal APIs that accept form data without an antiforgery token.
- The form field name `"images"` matches the client's `<input type="file" name="images" multiple />` or the equivalent `multipart/form-data` part name.

**Example `curl` call:**

```bash
curl -X POST http://localhost:5000/upload \
  -F "description=My vacation photos" \
  -F "images=@photo1.jpg" \
  -F "images=@photo2.png"
```
